import sys; sys.path.insert(0,'/home/claude/skripty')
from stranka import zapis
O='/home/claude/dokuio.com/src/obsah/ee/'
P=lambda n,p:{'nazev':n,'popis':p}
K3=[('Täitke andmed','Mida te ei tea, jätke vahele – jääb joon käsitsi täitmiseks.'),('Kontrollige teksti','Iga lõiku saate muuta.'),('Laadige alla ja allkirjastage','PDF või Word, tasuta.')]
PRIV=('Kas salvestate minu andmeid?','Ei. Dokument luuakse otse teie brauseris, andmeid serverisse ei saadeta.')
VOS='Põhi tugineb võlaõigusseaduse sätetele.'
def d(slug, ident, nazev, nazevA, popis, kat, il, slova, title, desc, perex, obsahPopis, obsah, online, hodi, nehodi, po, faq, zakony, vt, vd):
    landing={'title':title,'description':desc,'perex':perex,'obsahPopis':obsahPopis,'obsah':[P(*x) for x in obsah],'kroky':[P(*x) for x in K3],'online':online,'hodiSe':hodi,'nehodiSe':nehodi,'po':[P(*x) for x in po],'faq':[{'q':q,'a':a} for q,a in faq+[PRIV]],'zakony':zakony,'souvisejiciPopis':'Muud dokumendid, samuti tasuta.'}
    if not 70<=len(desc)<=170: print('DESC',slug,len(desc))
    if len(title.replace('{rok}','2026'))>70: print('TITLE',slug,len(title.replace('{rok}','2026')))
    if not 30<=len(vd)<=170: print('VD',slug,len(vd))
    if len(vt)>70: print('VT',slug,len(vt))
    for w in ('näidis','PDF','tasuta'): assert w in title, (slug,w)
    zapis(O+slug+'.ts','ee',slug,ident,nazev,nazevA,{'popis':popis,'kategorie':kat,'ilustrace':il,'slova':slova},kat,landing,{'title':vt,'description':vd,'podnadpis':'Tasuta · tulemus PDF-i ja Wordina · võtab mõne minuti'})

